	static final int N = (int)Math.pow(2,15)+1;
	static boolean[] is_prime = new boolean[N + 1];
	static int[] prime = new int[N];

	static void sieve() {
		int p = 0;
		for (int i = 0; i <= N; i++)
			is_prime[i] = true;
		is_prime[0] = is_prime[1] = false;
		for (int i = 2; i <= N; i++) {
			if (is_prime[i]) {
				prime[p++] = i;
				for (int j = 2 * i; j <= N; j += i)
					is_prime[j] = false;
			}
		}
	}

	static int si() {
		return Integer.parseInt(scan.next());
