		h = sc.nextInt();
		if ((h | w) == 0)
			return false;
		s = new int[w][h];
		dis = new int[w][h][4];
		for (int i = 0; i < w; i++) {
			for (int j = 0; j < h; j++) {
				Arrays.fill(dis[i][j], INF);
			}
		}
		cs = new int[5];
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				s[j][i] = sc.nextInt();
			}
		}
		for (int i = 0; i < 4; i++) {
			cs[i] = sc.nextInt();
		}
		cs[4] = 0;
		return true;
	}

	void run() {
		while (init()) {
			dis[0][0][0] = 0;
			while (true) {
				boolean update = false;
				for (int x = 0; x < w; x++) {
					for (int y = 0; y < h; y++) {
						for (int d = 0; d < 4; d++) {
							// コマンド0,1,2,3orパネルの命令
							for (int i = 0; i < 5; i++) {
