    }
    //２分探索
    static int binarySearch (double key, int[] array) {
        int left = -1;
        int right = array.length;
        while (right - left > 1) {
            int mid = (left + right)/2;
            if (array[mid] >= key) {
                right = mid;
            } else {
                left = mid;
            }
        }
        return right;
    }
