			int a = as[j];
			int curr = map.get(a);
			if (curr == n - 1) {
				map.put(a, 0);
				set.add(a);
			} else {
				map.put(a, curr + 1);
			}
			j++;
		}

		for (int i = 1; i <= m; i++) {
			if (map.get(i) > 0 && !set.contains(i)) {
				System.out.println("No");
				return;
			}
		}
		System.out.println("Yes");
	}
	public static boolean is(int[] as, int j, int m){
		if (j + m > as.length)
			return false;
		Set<Integer> set = new HashSet<>();
		for (int i = j ; i < j+m; i++){
			if (set.contains(as[i])){
