    			char[] inputs = sc.next().toCharArray();

    			for(int j = 0; j < W; j++){
    				if(inputs[j] == '#'){
    					is_wall[i][j] = true;
    				}else if(inputs[j] == 'N'){
    					sx = j;
    					sy = i;
    					sdir = NORTH;
    				}else if(inputs[j] == 'E'){
    					sx = j;
