    		long[][][] visit_time = new long[H][W][DIRS];
    		for(int i = 0; i < H; i++){
    			for(int j = 0; j < W; j++){
    				for(int k = 0; k < DIRS; k++){
    					visit_time[i][j][k] = -1;
    				}
    			}
    		}
