		if(rank[i] != rank[j]){
			return rank[i] < rank[j];
		}
		else {
			int ri = i + k <= n ? rank[i + k] : -1;
			int rj = j + k <= n ? rank[j + k] : -1;
			return ri < rj;
		}
	}

	static void constructSA(String s){
		n = s.length();

		sa = new Integer[n + 1];

		for(int i = 0; i < sa.length; i++){
			sa[i] = 0;
		}

		for(int i = 0; i <= n; i++){
			sa[i] = i;
			rank[i] = i < n ? s.charAt(i) : -1;
