						int rj = j + k <= n ? rank[j + k] : -1;
						return ri - rj;
					}
				}
			});

			tmp[sa[0]] = 0;
			for(int i = 1; i <= n; i++){
				tmp[sa[i]] = tmp[sa[i- 1]] + (compareSA(sa[i - 1], sa[i], n, k) ? 1 : 0);
