			e.time = i * 5;
			e.num = i % 5 == 1 ? 5 : 2;
			e.duration = 17*(i%2) + 3*(i%3)+19;
			pq.add(e);
		}
		while (!pq.isEmpty()) {
			Event e = pq.poll();
			if (e.move == Event.LEAVE) {
				for (int i = 0; i < table.length; i++) {
					if (table[i] == e.id) table[i] = -1;
				}
			} else if (e.move == Event.ARRIVE) {
				int pos = -1;
				if (nextGroup == e.id) {
					for (int i = 0; i + e.num <= table.length; i++) {
						boolean ok = true;
						for (int j = 0; j < e.num; j++) {
							if (table[i+j] != -1) {
								ok = false;
								break;
							}
						}
						if (ok) {
							pos = i;
							break;
						}
					}
				}
