					// 座る
					ans[e.id] = e.time - e.initTime;
					for (int j = 0; j < e.num; j++) {
						table[pos + j] = e.id;
					}
					e.time += e.duration;
					e.move = Event.LEAVE;
					pq.add(e);
					nextGroup++;
				} else {
					// 空いてなければ待つ。時刻+1して席が空くのを待つ手抜き実装
					e.time++;
					pq.add(e);
				}
