		while(true)
		{
			n = sc.nextInt();

			if(n == 0)
			{
				break;
			}

			System.out.println(countPair(n));
		}

	}

	private static void init()
	{
		prime = new boolean[MAX];

		for(int i = 0; i < MAX; i++)
		{
			prime[i] = isPrime(i);
		}
	}

	public static int countPair(int n)
	{
		int cnt = 0;

		for(int i = 2; 2 * i < n; i++)
		{
			if(i % 2 == 0)
			{
				continue;
			}

			if(isPairable(i, n) && prime[i])
			{
				cnt++;
			}	
		}

		return cnt;
	}

	// if p2 is prime or not.
	public static boolean isPairable(int p1, int n)
	{
		return prime[n - p1];
	}

	private static boolean isPrime(int n)
	{
		if(n <= 1)
		{
			return false;
		}
		else if(n == 2)
		{
			return true;
		}
		else if(n % 2 == 0)
		{
			return false;
		}
		else
		{
			for(int i = 3; i * i <= n; i += 2)
			{
				if(n % i == 0)
				{
					return false;
				}
			}
		}
		return true;
	}
}
