				B[i] = Arrays.binarySearch(posY, B[i]);
				for (int j = B[i]; j < T[i]; ++j) {
					for (int k = L[i]; k < R[i]; ++k) {
						v[j][k] |= (1L << i);
					}
				}
			}
			int ans = 0;
