	int numbering(int[] permutation) {
		int factorial = 1;
		int ret = 0;
		for (int i = 0; i < permutation.length; i++) {
			int count = 0;
			for (int j = i - 1; j >= 0; j--) {
				if (permutation[i] > permutation[j])
					count++;
			}
			if (i != 0)
				factorial *= i;
			ret += factorial * count;
		}
		return ret;
	}

	long to_long(int[] array) {
