        long countB = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            countA = binarySearch(b[i] - 0.1, a);
            if (countA < 0) continue;
            countB = n - binarySearch(b[i] + 0.1, c);
            if (countB < 0) continue;
