            if((N-1)%k!=0 && isFeasible(N, k)){
                res++;
            }
        }
        System.out.print(res);
    }

    public static boolean isFeasible(long N, long k){
        if(N%k==0){
            while(N%k==0){
                N = N/k;
            }
            return N%k==1;
        }
        return false;
    }

    public static long count(long n){
        int res = 0;
        for(long i=2; i<=Math.sqrt(n); i++){
            if(n%i==0){
                res+=1;
                if(i*i!=n){
                    res++;
                }
            }
        }
        return res;
    }
}
