		out.flush();
	}

	static int gcd(int a, int b) {
		return b == 0 ? a : gcd(b, a%b);
	}

	static boolean divides(long[] pol, int p) {
		int n = pol.length - 1;
		while (n >= p) {
			pol[n - p + 1] += pol[n];
			pol[n] = 0;
			n--;
		}
		for (int i = 0; i < p && i < pol.length; i++) {
			if (pol[i] % p != 0) return false;
		}
		return true;
	}

